import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';
import { CurrencyCode } from '../clients/client.service';

export type ProjectStatus = 'ACTIVE' | 'ON_HOLD' | 'FINISHED';

/** The statuses a project can be marked with, in the order they are offered. */
export const PROJECT_STATUSES: { value: ProjectStatus; label: string }[] = [
  { value: 'ACTIVE', label: 'Active' },
  { value: 'ON_HOLD', label: 'On hold' },
  { value: 'FINISHED', label: 'Finished' },
];

export interface Project {
  id: number;
  name: string;
  /** Short reference code, unique across jobs; null for jobs added before codes existed. */
  code: string | null;
  clientId: number;
  clientName: string;
  archived: boolean;
  status: ProjectStatus;
  /** The currency of the client the job is for. */
  currency: CurrencyCode;
  /** A short description of the work; null when none was given. */
  description: string | null;
  /** Whether the work is charged to the client; internal work is non-billable. */
  billable: boolean;
  /** Whether the job is closed; no new invoice can be raised on a closed job. */
  closed: boolean;
  /** The day work on the job starts (YYYY-MM-DD); null when not set. */
  startDate: string | null;
  /** The day work on the job ends (YYYY-MM-DD); null when not set. */
  endDate: string | null;
  /** A reference to a file kept elsewhere for the job (e.g. a document number); null when none was noted. */
  fileRef: string | null;
  /** The category the job is put into (e.g. "Web"); null when it has none. */
  category: string | null;
}

/** A project's budget, what has been invoiced against it, and what is left; null when no budget is set. */
export interface ProjectBudget {
  budget: number | null;
  invoiced: number;
  remaining: number | null;
}

export interface NewProject {
  name: string;
  code: string;
  clientId: number;
  status: ProjectStatus;
  description: string | null;
}

@Injectable({ providedIn: 'root' })
export class ProjectService {
  private readonly http = inject(HttpClient);

  list(
    includeArchived = false,
    tagId: number | null = null,
    status: ProjectStatus | null = null,
  ): Observable<Project[]> {
    const params: Record<string, string | number | boolean> = { includeArchived };
    if (tagId !== null) {
      params['tagId'] = tagId;
    }
    if (status !== null) {
      params['status'] = status;
    }
    return this.http.get<Project[]>('/api/projects', { params });
  }

  listForClient(clientId: number, includeAll = false): Observable<Project[]> {
    return this.http.get<Project[]>(`/api/clients/${clientId}/projects`, {
      params: { includeAll },
    });
  }

  get(id: number): Observable<Project> {
    return this.http.get<Project>(`/api/projects/${id}`);
  }

  create(project: NewProject): Observable<Project> {
    return this.http.post<Project>('/api/projects', project);
  }

  changeStatus(id: number, status: ProjectStatus): Observable<Project> {
    return this.http.put<Project>(`/api/projects/${id}/status`, { status });
  }

  setBillable(id: number, billable: boolean): Observable<Project> {
    return this.http.put<Project>(`/api/projects/${id}/billable`, { billable });
  }

  setDates(id: number, startDate: string | null, endDate: string | null): Observable<Project> {
    return this.http.put<Project>(`/api/projects/${id}/dates`, { startDate, endDate });
  }

  setFileRef(id: number, fileRef: string | null): Observable<Project> {
    return this.http.put<Project>(`/api/projects/${id}/file-ref`, { fileRef });
  }

  setCategory(id: number, category: string | null): Observable<Project> {
    return this.http.put<Project>(`/api/projects/${id}/category`, { category });
  }

  budget(id: number): Observable<ProjectBudget> {
    return this.http.get<ProjectBudget>(`/api/projects/${id}/budget`);
  }

  setBudget(id: number, budget: number | null): Observable<ProjectBudget> {
    return this.http.put<ProjectBudget>(`/api/projects/${id}/budget`, { budget });
  }

  close(id: number): Observable<Project> {
    return this.http.post<Project>(`/api/projects/${id}/close`, null);
  }

  reopen(id: number): Observable<Project> {
    return this.http.post<Project>(`/api/projects/${id}/reopen`, null);
  }

  archive(id: number): Observable<Project> {
    return this.http.post<Project>(`/api/projects/${id}/archive`, null);
  }

  restore(id: number): Observable<Project> {
    return this.http.post<Project>(`/api/projects/${id}/restore`, null);
  }
}
